test("DateTime#plus works across the 100 barrier when passing through February", () => {
  // 100 is NOT a leap year under the proleptic Gregorian rule
  expect(DateTime.local(100, 1, 31).plus({ months: 1 }).toISODate()).toBe("0100-02-28");
  expect(DateTime.local(100, 2, 28).plus({ days: 1 }).toISODate()).toBe("0100-03-01");
  // 104 IS a leap year
  expect(DateTime.local(104, 2, 28).plus({ days: 1 }).toISODate()).toBe("0104-02-29");

  expect(DateTime.local(100, 2, 28).isInLeapYear).toBe(false);
  expect(DateTime.local(104, 2, 28).isInLeapYear).toBe(true);

  // The actual 100-barrier crossing: starting in year 99 and passing through Feb of year 100.
  // Year 100 is not a leap year, so Dec 31 0099 + 59 days = Feb 28 0100, + 60 = Mar 1 0100,
  // + 61 = Mar 2 0100 (the buggy code collapsed 60 and 61 both onto Mar 1).
  expect(DateTime.fromISO("0099-12-31").plus({ days: 59 }).toISODate()).toBe("0100-02-28");
