  expect(DateTime.fromISO("0099-12-31").plus({ days: 61 }).toISODate()).toBe("0100-03-02");
  expect(DateTime.fromISO("0099-12-31").plus({ days: 90 }).toISODate()).toBe("0100-03-31");
  expect(DateTime.fromISO("0099-12-31").plus({ months: 2 }).toISODate()).toBe("0100-02-28");
